extension FollowUpCases {
    static let batchAK: [CaseTemplate] = [chainsawResale, secondPowerOfAttorney, boatWhileImpaired, schoolPickupStalking, utilityAccountFraud]

    // MARK: - After the Marketplace trailer

    static let chainsawResale = followUp(
        key: "story.followup.chainsawResale", category: .property,
        headlines: ["Stolen Chainsaws Found in Small Engine Shop", "Equipment Dealer Charged Again in Stolen Goods Case"],
        law: "possStolen", threshold: 6, spec: "Possessed six chainsaws and two pressure washers valued at $6,300, the property of {V}, knowing and having reasonable grounds to believe them stolen, on {DATE}.", ages: 22...58, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a rental store owned by {V} lost six chainsaws and two pressure washers in a break-in. Two weeks later a deputy found all eight in {D}'s shop with the rental store's inventory stickers peeled off but the adhesive outline still there. {DL} says {D.he} took them in on trade from a customer {D.he} can't name.",
        state: [E(.physical, 3, "Equipment", "Eight units with the rental store's sticker outlines still visible; serials match the store's inventory.", .search),
                E(.document, 2, "Trade Log", "{DL}'s shop log shows no trade-in entry for any of the eight.")],
        defense: [E(.statement, 1, "Trade-In", "{DL} says a customer traded them for a rebuilt mower and {D.he} didn't write it down.")],
        witnessRole: "Sheriff's property crimes detective",
        exam: [.direct("What did you find?", "\"All eight items, stickers peeled, outlines still on the housings. Serials match.\""),
               .direct("Was there a record of a trade?", "\"No. And this is a dealer who was just in court for not keeping records.\""),
               .direct("What was taken from the rental store?", "\"Six chainsaws and two pressure washers, in a break-in. {V} gave us the inventory list with serial numbers.\""), .direct("Where did you find the equipment?", "\"Two weeks later, in {DL}'s shop. All eight units were there, with the rental store's inventory stickers peeled off but the adhesive outlines still visible.\""), .direct("Did {DL} have records for the equipment?", "\"No. {DL}'s shop log shows no trade-in entry for any of the eight.\""), .direct("What did {DL}'s phone show?", "\"Texts arranging a 'trade' the morning after the break-in. They do not name a customer.\""),
                    .cross("{DL} didn't break into the rental store.", "\"We're not saying {D.he} did.\""),
               .cross("Customers do trade equipment.", "\"With a name and a receipt, usually.\""),
                    .cross("{DL} is not accused of the break-in?", "\"We are not saying {D.he} did it. The charge is possession of stolen property, which depends on what {D.he} knew.\""), .cross("Dealers do take trade-ins, don't they?", "\"They do, usually with a name and a receipt. {DL} had neither.\""), .cross("The burglar was caught later?", "\"He was, and he said he sold the saws to a flea market vendor who resold them to {DL} with the stickers already peeled.\"")],
        theory: ("A dealer already caught once took in stolen equipment again and peeled off the stickers.", "A trade-in {DL} didn't write down."),
        allocution: "\"A customer traded those saws in at my shop, and I don't remember the name. I should have written it down. I'm closing the shop, and I can't keep doing this.\"",
        truths: ("{DL}'s phone had texts arranging the 'trade' the morning after the break-in.",
                 "The burglar, caught later, said he'd sold the saws to a flea market vendor who resold them to {DL} with the stickers already peeled."),
        defendant: [.direct("Where did the saws come from?", "\"A customer traded them in.\""),
               .direct("Who?", "\"I don't remember the name.\""),
               .direct("Who was the customer?", "\"I do not remember his name. He was a walk-in, and I did not write down his information.\""),
               .direct("Did you notice the sticker outlines?", "\"No. I did not notice. I saw the saws and the washers and thought they were good used equipment.\""),
               .direct("What did you plan to do with them?", "\"Sell them in the shop at a fair price. I do that with trade-ins all the time, and it is part of my business.\""),
               .direct("How long have you owned the shop?", "\"Eleven years. I buy and sell used equipment, and I keep a shop log for most deals, though not every trade-in.\""),
                    .cross("After your last case, you didn't keep a record?", "\"After my last case, I should have kept a record, and I didn't.\""),
               .cross("The sticker outlines are still on them.", "\"I didn't notice. The sticker outlines are still on them, but I didn't see that.\""),
               .cross("The outlines are still on the housings.", "\"I did not see that. They are there, and I understand it looks bad.\""),
               .cross("The texts were the morning after the break-in.", "\"I got a message from a man about a trade. I did not know the tools came from a break-in.\""),
                    .cross("You peeled the stickers off or someone did.", "\"I did not peel them. They were like that when the saws came in, and I did not look closely at the housings.\"")],
        openings: ("A rental store owned by {V} lost six chainsaws and two pressure washers in a break-in, and two weeks later a deputy found all eight in {D}'s shop with the inventory stickers peeled off, the adhesive outlines still visible, and no trade-in record.", "The defense will say a customer traded the equipment for a rebuilt mower, and {D} did not write it down or notice the sticker outlines. {D} is not accused of the break-in."),
        closings: ("Eight items with {V}'s serial numbers, sticker outlines still on them, and no record of any trade, from a dealer who had just been in this court over {PRIOR} for keeping no records.", "The burglar said he sold the saws to a vendor who resold them to {D} with the stickers already peeled. The State must prove {D} knew they were stolen."),
        timeline: [(-14, "Break-in at {V}'s rental store."), (0, "Deputy finds the equipment at {DL}'s shop.")],
