    // MARK: - After the power of attorney

    static let secondPowerOfAttorney = followUp(
        key: "story.followup.secondPowerOfAttorney", category: .whiteCollar,
        headlines: ["Man Convicted in Aunt's Case Took Over Another Elder's Finances", "Second Exploitation Charge for Nephew in Power of Attorney Case"],
        law: "exploitationElder", threshold: 6, spec: "Being in a position of trust and confidence with {V}, an older adult, knowingly by deception used {V}'s funds for {D.his} own benefit, $18,200, on {DATE}.", ages: 35...65, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} began \"helping\" {V}, an 81-year-old widower at {D.his} church, with bills. {V} added {DL} to {V.his} checking account. Over five months, $18,200 went to {DL}'s credit card bills and a used boat. {V}'s son found the statements when his father's power bill went unpaid.",
        state: [E(.document, 3, "Bank Records", "$18,200 from {V}'s account to {DL}'s credit cards and a boat dealer."),
                E(.document, 2, "Church Records", "{DL} signed up as a volunteer driver for homebound members two weeks after the earlier case ended.")],
        defense: [E(.statement, 1, "Gifts", "{DL} says {V} wanted to help {D.him} get back on {D.his} feet.")],
        witnessRole: "Adult Protective Services social worker",
        exam: [.direct("What did you find?", "\"A joint account with {DL} added, and almost every withdrawal went to {DL}'s bills.\""),
               .direct("What does {V} say?", "\"That {DL} was a nice young man from church who helped with the mail.\""),
               .direct("How did {DL} come to know {V}?", "\"{DL} was a volunteer driver at {V}'s church, and began 'helping' {V}, an 81-year-old widower, with bills.\""),
               .direct("What changed on {V}'s bank account?", "\"{V} added {DL} to the checking account. Over five months, $18,200 went to {DL}'s credit card bills and a used boat.\""),
               .direct("How was it discovered?", "\"{V}'s son found the statements and brought them to us. {V}'s power bill had gone unpaid while the money was leaving.\""),
               .direct("What did you learn about {DL}'s history?", "\"{DL} signed up as a church volunteer driver two weeks after the earlier case ended. {V} did not know about that case.\""),
               .cross("{V} added {DL} to the account voluntarily.", "\"{V.He} did. {V.He} didn't know about the earlier case.\""),
               .cross("Joint owners can withdraw money.", "\"Not to deceive the other owner.\""),
               .cross("{V} added {DL} voluntarily, didn't {V.he}?", "\"{V.He} did. {V.He} thought {DL} was a nice young man from church who helped with the mail.\""),
               .cross("{V} wrote some of the payments in a ledger?", "\"{V}'s own ledger records several as 'loans to my friend, gladly.' {V} says he did not know the boat was part of it.\""),
                    .cross("{V} wanted to help {DL}?", "\"{V} says so in the ledger, which calls some payments loans to a friend, gladly. {V}'s son found the statements and did not agree.\"")],
        theory: ("{D} did it again: a new church, a new widower, and {V.his} money on {DL}'s bills.", "A lonely man's gifts to a friend."),
        allocution: "\"I began helping {V} with bills at church, and {V.he} wanted to help with mine. {V.He} said get something for yourself. This was different from last time, and I know how it looks. I need help. I keep doing this, and I'm sorry.\"",
        truths: ("{DL} told the boat dealer, \"My uncle's paying for it, he'll never notice.\"",
                 "{V}'s own notes, kept in a ledger, recorded several of the payments as \"loans to my friend, gladly.\""),
        defendant: [.direct("Why did {V} add you to the account?", "\"To help with {V.his} bills. {V.He} wanted to help with mine too.\""),
               .direct("Did {V} know about the boat?", "\"{V.He} said get something for yourself.\""),
               .direct("How did you help {V}?", "\"I drove {V.him} to church and to the pharmacy, and I helped {V.him} sort through the mail and pay bills.\""),
               .direct("Why were you added to the account?", "\"{V} wanted me to be able to help with the bills, and I helped {V.him} write checks. {V.He} wanted to help me too.\""),
               .direct("What about the boat?", "\"{V} said to get something for myself. I bought a used boat, and I thought {V.he} knew.\""),
               .direct("What did you say to the boat dealer?", "\"I told him my uncle was paying for it. I said that because I was embarrassed that {V} was helping me.\""),
               .cross("After what happened with your aunt, you did this again.", "\"What happened with my aunt was a different situation from this one.\""),
               .cross("{V}'s power bill went unpaid while you bought a boat.", "\"I didn't know about the power bill.\""),
               .cross("You told the dealer your uncle was paying.", "\"I said it to explain why I did not have the money. I know it was not true.\""),
                    .cross("{V}'s son found the bank statements.", "\"He did, and I understand why he was upset. I thought {V} wanted me to have the help.\""), .cross("You added your name to an 81-year-old man's account.", "\"I did, at {V.his} request. I should have talked to the family first.\"")],
        openings: ("{D} began 'helping' {V}, an 81-year-old widower at {D}'s church, with bills, and {V} added {D} to {V.his} checking account. Over five months $18,200 went to {D}'s credit card bills and a used boat while {V}'s power bill went unpaid.", "The defense will say {V} wanted to help {D} get back on {D.his} feet, added {D} to the account, and said to get something for {D.himself}. {V}'s own ledger records some of the payments as loans to a friend, gladly."),
        closings: ("A joint account, $18,200, a used boat, and a dealer told 'my uncle's paying for it, he'll never notice.' {D} was back after {PRIOR}, with another widower at another church.", "A lonely man gave gifts to a friend and wrote them in his own ledger. The State must prove {V} did not understand and that {D} took advantage."),
        timeline: [(-150, "{DL} added to {V}'s account."), (0, "{V}'s son finds the statements.")],
        identified: "{V}'s son and the bank statements.",
        impact: "{V}'s son: \"Dad trusted everybody at that church, and we found out someone had taken over eighteen thousand dollars from his account. He's eighty-one and doesn't answer the door anymore. It has changed how he sees the very people who sit beside him on Sundays.\"")

    // MARK: - After the golf cart

    static let boatWhileImpaired = followUp(
        key: "story.followup.boatWhileImpaired", category: .traffic,
        headlines: ["Driver in Golf Cart Death Charged After Boat Crash", "Impaired Driving Charge Follows Second Crash"],
        law: "dwi", threshold: 5, spec: "Drove a vehicle on a street or highway in Hollis County while subject to an impairing substance, on {DATE}.", ages: 24...62, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, Highway Patrol stopped {D} at 1 a.m. on {DATE} on the causeway after {D.his} SUV drifted across the center line twice. {DL} blew 0.13 on the roadside test and 0.12 on the Intoxilyzer at the jail. A cooler of beer was open on the passenger floor.",
        state: [E(.document, 3, "Intoxilyzer Result", "0.12 at 1:52 a.m.; the 15-minute observation period logged."),
                E(.video, 2, "Dash Camera", "The SUV crosses the center line twice on the causeway.")],
        defense: [E(.statement, 1, "Wind", "{DL} says crosswinds on the causeway pushed the SUV.")],
        witnessRole: "Highway Patrol trooper",
        exam: [.direct("Why did you stop {DL}?", "\"Crossed the center line twice in half a mile.\""),
               .direct("What did you see in the car?", "\"An open cooler of beer and the smell of alcohol.\""),
               .direct("What did you observe in the SUV?", "\"The smell of alcohol and an open cooler of beer on the floor. {DL}'s eyes were red and {D.his} speech was slow.\""),
               .direct("What were the test results?", "\"0.13 on the roadside test and 0.12 on the Intoxilyzer at the jail at 1:52 a.m. The fifteen-minute observation period was logged.\""),
               .direct("What did the dash camera show?", "\"The SUV crossing the center line twice on the causeway. It does not show any wind effect.\""),
               .direct("How did {DL} perform on the field tests?", "\"{D.He} swayed on the one-leg stand and missed the heel-to-toe line twice. I recorded each of those on my sheet.\""),
                    .cross("The causeway is windy.", "\"It was calm that night.\""),
               .cross("The roadside test isn't admissible as a number.", "\"That is correct, and I rely on the Intoxilyzer reading, which is admissible. The roadside number only told me why to take {D.him} to the jail.\""),
               .cross("The Intoxilyzer was reading high?", "\"The calibration log, reviewed later, showed it reading high that month. I was not told about that at the time.\""),
                    .cross("Cold air and a long day can affect balance, can't they?", "\"They can. I take that into account, which is why the Intoxilyzer reading at the jail matters to me more than the roadside tests.\""), .cross("The bar receipt does not carry {DL}'s name?", "\"It was in {DL}'s wallet, and it showed nine drinks that night. I do not know whose drinks they were.\"")],
        theory: ("After a friend died in a crash {D.he} caused, {D} drove impaired again.", "Wind on a causeway and a machine."),
        allocution: "\"I had two beers at dinner, and the wind pushed the boat. I haven't forgiven myself, and I've been drinking to forget it. I'll get treatment, and I'm sorry to the patrol.\"",
        truths: ("A bar receipt in {DL}'s wallet showed nine drinks that night.",
                 "The Intoxilyzer's calibration log, reviewed later, showed it reading high that month."),
        defendant: [.direct("How much had you had?", "\"Two beers at dinner. That's all I had, and I stopped a couple of hours before driving.\""),
               .direct("Why cross the line?", "\"The wind. A gust pushed the car across the line, and I corrected right away.\""),
               .direct("How much did you have to drink?", "\"Two beers at dinner. That is all I had, and I stopped a couple of hours before driving.\""),
               .direct("What was in the cooler?", "\"Beer from the beach, left on the floor from the weekend. I had not opened one while driving.\""),
               .direct("How did you feel when you were stopped?", "\"Nervous. I had been through this before, and I knew how it looked.\""),
               .direct("Where were you before you drove?", "\"At a bar down the causeway with friends, for a few hours. I had beer there, not just at dinner.\""),
                    .cross("After your friend died in that golf cart.", "\"I know. My friend died in that golf cart, and I've thought about it every day.\""),
               .cross("An open cooler on the floor.", "\"It was from the beach.\""),
               .cross("A bar receipt in your wallet shows nine drinks.", "\"That was from a different night. I do not know how it got into my wallet.\""),
                    .cross("You told the trooper two beers at dinner.", "\"I said that, and it was not the whole truth. I was afraid of what would happen to me.\""), .cross("You drove across a causeway at one in the morning after drinking.", "\"I did, and I should not have. I was tired, and I thought I could make it home.\"")],
        openings: ("Highway Patrol stopped {D} at 1 a.m. on the causeway after {D.his} SUV drifted across the center line twice. {D} blew 0.13 on the roadside test and 0.12 on the Intoxilyzer, and a cooler of beer was open on the floor.", "The defense will say crosswinds on the causeway pushed the SUV, and the Intoxilyzer's calibration log shows it reading high that month. {D} had two beers at dinner."),
        closings: ("Two lane crossings, a 0.12 on the Intoxilyzer, a cooler of beer on the floor, and a bar receipt showing nine drinks, from a driver whose friend died in a crash {D} caused over {PRIOR}.", "The wind blows on a causeway, and a machine that reads high cannot be trusted. The State must prove {D} was over the limit when {D.he} drove."),
        timeline: [(0, "1 a.m.: stop on the causeway; 1:52 a.m.: Intoxilyzer.")],
        identified: "A Highway Patrol stop.",
        impact: nil,
        doctrines: ["burdenOfProof"])

    // MARK: - After the birthday party

    static let schoolPickupStalking = followUp(
        key: "story.followup.schoolPickupStalking", category: .robbery,
        headlines: ["Ex-Husband Seen at School Pickup Line Despite Order", "Second Stalking Charge After School Pickup"],
        law: "stalkingCourtOrder", lesser: "stalking", threshold: 6, spec: "On more than one occasion followed and watched {V} without legal purpose while a protective order prohibiting that conduct was in effect, causing {V} to fear for {V.his} safety, on {DATE}.", ages: 26...48, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s protective order was renewed. On {DATE}, school staff saw {D} parked across from the elementary school's pickup line three afternoons in one week, watching {V}'s car. The school's camera recorded his truck each time, and the principal called deputies on the third day.",
        state: [E(.video, 3, "School Camera", "{DL}'s truck across from the pickup line three afternoons, 20 to 40 minutes each."),
                E(.document, 2, "Renewed Order", "Stay 500 feet from {V} and the child's school.")],
        defense: [E(.statement, 1, "Daughter", "{DL} says he only wanted to see his daughter come out of school.")],
        witnessRole: "School principal",
        exam: [.direct("What did you see?", "\"The same truck three afternoons, engine running, facing the pickup line.\""),
               .direct("Did he come onto school grounds?", "\"No. He just watched. He stayed off school grounds.\""),
               .direct("What is the order?", "\"{V}'s protective order was renewed after the earlier case. It requires {DL} to stay 500 feet from {V} and from the child's school.\""),
               .direct("What did school staff see?", "\"{DL}'s truck parked across from the elementary school's pickup line on three afternoons in one week, for 20 to 40 minutes each time.\""),
               .direct("How did {DL} behave?", "\"He sat with the engine running, facing the line, watching {V}'s car. He did not get out and did not come onto school grounds.\""),
               .direct("What was found in {DL}'s phone?", "\"A text to a friend: 'she can't hide the kid from me, I know her schedule.'\""),
               .cross("He never approached anyone.", "\"No. He didn't have to.\""),
               .cross("He has custody time with the child.", "\"Not at my pickup line.\""),
               .cross("{DL}'s counselor told him to drive by?", "\"A note in his records says his counselor suggested it as exposure therapy. I did not know that when I called the deputies.\""),
                    .cross("{DL} stayed in his truck, didn't he?", "\"He did. He never got out, never spoke to anyone, and never approached {V}'s car.\""), .cross("{DL}'s counselor suggested he drive past the school?", "\"A note in his records says so. I did not know of it, and the order does not carve out exceptions for therapy.\"")],
        theory: ("Under a renewed order, {D} sat outside the school three afternoons watching {V}.", "A father watching his daughter walk out of school."),
        allocution: "\"I only wanted to see my daughter walk out of school. That's all. I was across the street and never went close. I'll stay away, and I'll do the classes. I just miss her. I'm sorry to {V} and to the school.\"",
        truths: ("{DL} had texted a friend, \"she can't hide the kid from me, I know her schedule.\"",
                 "{DL}'s counselor had told him to drive by the school as part of 'exposure therapy,' a note in his records shows."),
        defendant: [.direct("Why were you at the school?", "\"To see my daughter walk out. That's all.\""),
               .direct("Did you speak to anyone?", "\"No. I didn't speak to anyone, and I left right after.\""),
               .direct("Did you watch {V}?", "\"I looked at the cars in the line. I did not follow {V} or speak to anyone.\""),
               .direct("Why did you go three times?", "\"It helped me. My counselor told me to drive by the school as part of my treatment, and I thought that meant I could.\""),
               .direct("How far away were you?", "\"Across the street. I did not think I was within 500 feet, and I never measured.\""),
               .direct("Did you see {V} at the school?", "\"I saw {V}'s car in the line. I did not look at {V.him}, and I did not speak to {V.him}.\""),
               .cross("The order says 500 feet from that school.", "\"I was across the street.\""),
               .cross("Three afternoons, right after your last case.", "\"I know how it looks.\""),
               .cross("You texted that she cannot hide the child.", "\"I was upset when I sent it. I did not mean it the way it sounds.\""),
                    .cross("You knew the order covered the school.", "\"I knew there was an order. I did not think a parked truck across the street broke it.\""), .cross("Your truck was there three afternoons.", "\"It was. I wanted to see my daughter, and I told myself I was not doing any harm.\"")],
        openings: ("{V}'s protective order was renewed, requiring {D} to stay 500 feet from {V} and from the child's school. On three afternoons in one week school staff saw {D}'s truck across from the pickup line for 20 to 40 minutes, watching {V}'s car.", "The defense will say {D} only wanted to see {D.his} daughter walk out of school, stayed across the street, and was following a counselor's suggestion to drive by. {D} never approached anyone."),
        closings: ("Three afternoons, twenty to forty minutes each, watching {V}'s car, after a renewed order and a text, 'she can't hide the kid from me.' {D} was back after {PRIOR}.", "A father with a counselor's note watched his daughter walk out of school from across the street. The State must prove {D} knew the order covered that spot and meant to watch {V}."),
        timeline: [(-4, "First afternoon at the school."), (0, "Third afternoon; principal calls deputies.")],
        identified: "The school's camera and staff.",
        impact: "\"I changed my daughter's school in the middle of the year because of that car at the pickup line. It was parked across from the school three afternoons in one week, watching us. She had to leave her friends, and I felt I had no other choice to keep her safe.\"")

    // MARK: - After the dead brother's name

    static let utilityAccountFraud = followUp(
        key: "story.followup.utilityAccountFraud", category: .whiteCollar,
        headlines: ["Utility Accounts Opened in Mother's Name, Deputies Say", "Identity Theft Defendant Charged Again"],
        law: "identityTheft", threshold: 6, spec: "Knowingly used the identifying information of {V} to fraudulently open utility and phone accounts, $3,900, on {DATE}.", ages: 28...58, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} moved into a rental house and opened the power, internet, and two phone lines in the name of {V}, {D.his} mother, who lives in a nursing home. The accounts ran up $3,900 unpaid before a collections letter reached the nursing home.",
        state: [E(.document, 3, "Account Records", "Four accounts opened online in {V}'s name, service address {DL}'s rental."),
                E(.document, 2, "Nursing Home Records", "{V} has lived in memory care for two years.")],
        defense: [E(.statement, 1, "Permission", "{DL} says his mother told him years ago he could use her name for anything he needed.")],
        witnessRole: "Sheriff's financial crimes detective",
        exam: [.direct("Whose address was on the accounts?", "\"The mail and the accounts went to {DL}'s rental house.\""),
               .direct("Could {V} have opened them?", "\"{V.He}'s in memory care. {V.He} doesn't use a computer.\""),
               .direct("What accounts were opened?", "\"Power, internet and two phone lines, all opened online in {V}'s name. The service address on all four was {DL}'s rental house.\""),
               .direct("How much went unpaid?", "\"$3,900, before a collections letter reached the nursing home.\""),
               .direct("Where does {V} live?", "\"In a nursing home, in memory care for two years. {V.he} does not use a computer.\""),
               .direct("What did you find on {DL}'s laptop?", "\"A spreadsheet of family members' Social Security numbers. {V}'s was on it.\""),
               .cross("{V} may have given permission years ago.", "\"For accounts that didn't exist then?\""),
               .cross("Family members share accounts.", "\"Not without telling the person.\""),
               .cross("{DL}'s sister was involved?", "\"{DL}'s sister later admitted opening the accounts in their mother's name and giving {DL} the logins.\""),
                    .cross("{DL}'s mother could have signed up in the past?", "\"Not for these accounts. They were opened online in the last few months, and {V} has not used a computer in years.\""), .cross("{DL}'s sister admitted opening the accounts?", "\"She admitted opening them and giving {D.him} the logins. {DL} used them, and the mail went to {D.his} rental.\"")],
        theory: ("After using a dead brother's name, {D} used {D.his} mother's.", "A son with his mother's blessing."),
        allocution: "\"Mama always said to use her name if I needed to, and she said it before. My credit is ruined, and I was trying to keep the lights on. I'll pay every bill. I'm sorry to the utility companies and to my mother.\"",
        truths: ("{DL}'s laptop held a spreadsheet of family members' Social Security numbers.",
                 "{DL}'s sister admitted opening the accounts in their mother's name and giving him the logins."),
        defendant: [.direct("Did you open the accounts?", "\"Mama always said use her name if I needed to.\""),
               .direct("Why not your own name?", "\"My credit's ruined. I couldn't open anything in my own name, and I was ashamed.\""),
               .direct("Why in your mother's name?", "\"Mama always said to use her name if I needed it. She said so before she went into memory care.\""),
               .direct("Did you tell her?", "\"I did not tell her, because she was already in memory care. I was handling some of her accounts, and I thought it was fine.\""),
               .direct("What about the spreadsheet?", "\"It was a list of family members' numbers that I kept for her medical forms. I did not use them to open anything.\""),
               .direct("Did your mother ever sign anything for you?", "\"Years ago, a power of attorney form at her bank. She said I could handle things for her if she got sick.\""),
